func moveStateWord(s string) string {
	switch s {
	case "running":
		return "Moving"
	case "failed":
		return "Failed"
	case "done":
		return "Done"
	}
	return s
}

func moveStateTone(s string) string {
	switch s {
	case "failed":
		return "danger"
	case "done":
		return "success"
	}
	return "warn"
}

